const ACTOR_ID='b0AZEdG2WGln6jZux';
const BUSINESS_TAB='BBB Businesses';
const RUN_TAB='BBB Runs';
const LOCK_TAB='_BBB_WORKFLOW_LOCK';
const BUSINESS_HEADERS=['sourceUrl','businessName','address','city','state','postalCode','bbbRating','accreditationStatus','bbbMember','categories','phone','firstSeenAt','lastSeenAt','lastRunId','search','searchLocation'];
const RUN_HEADERS=['runId','status','search','location','distanceMiles','startedAt','finishedAt','datasetId','rowsRead','rowsRejected','rowsAdded','rowsUpdated','duplicatesSkipped','estimatedResultChargeUsd','maxChargeUsd','buildNumber','executionId','notes'];
const MAX_EXISTING=5000;
const MAX_DATASET=1000;
function config(input){
 const c={...input};
 for(const k of ['search','location','spreadsheetId','resumeRunId'])c[k]=String(c[k]??'').trim();
 if(!c.search||!c.location)throw new Error('Fill in search and location in Configure search.');
 if(!/^[A-Za-z0-9_-]{20,100}$/.test(c.spreadsheetId))throw new Error('Paste the spreadsheet ID (not its URL) in Configure search before starting a paid run.');
 if(c.resumeRunId&&!/^[A-Za-z0-9]{17}$/.test(c.resumeRunId))throw new Error('resumeRunId must be the 17-character Apify run ID.');
 c.distanceMiles=Number(c.distanceMiles);c.maxChargeUsd=Number(c.maxChargeUsd);
 if(!Number.isInteger(c.distanceMiles)||c.distanceMiles<1||c.distanceMiles>100)throw new Error('distanceMiles must be an integer from 1 to 100.');
 if(!Number.isFinite(c.maxChargeUsd)||c.maxChargeUsd<0.01||c.maxChargeUsd>1)throw new Error('maxChargeUsd must be between 0.01 and 1 USD for this small-batch template.');
 return c;
}
function prepareSheet(meta){
 if(!Array.isArray(meta.sheets))throw new Error('Cannot read spreadsheet tabs. Check Google Sheets credentials.');
 const names=meta.sheets.map(s=>s.properties.title);
 if(names.includes(LOCK_TAB))throw new Error('BBB destination is locked. Another execution may be running. Inspect n8n and the BBB Runs tab; only after it is stopped, delete _BBB_WORKFLOW_LOCK and resume the saved run ID.');
 const requests=[{addSheet:{properties:{title:LOCK_TAB,gridProperties:{rowCount:5,columnCount:2}}}}];
 for(const title of [BUSINESS_TAB,RUN_TAB])if(!names.includes(title))requests.push({addSheet:{properties:{title,gridProperties:{rowCount:MAX_EXISTING+2,columnCount:20}}}});
 return {requests};
}
function validateTable(values,headers,label){
 if(!values?.length)return [];
 if(headers.some((h,i)=>values[0]?.[i]!==h))throw new Error(label+' headers do not match the template. Restore the documented managed columns; no paid run has started.');
 const rows=values.slice(1);
 if(rows.length>MAX_EXISTING)throw new Error(label+' exceeds 5000 rows. Archive into a separate spreadsheet before continuing.');
 const seen=new Set();
 for(const row of rows){
  if(!row[0]){if(row.some(v=>v!==''&&v!==null))throw new Error(label+' contains a row without its key.');continue;}
  if(seen.has(String(row[0])))throw new Error(label+' contains duplicate keys. Resolve duplicates before running.');
  seen.add(String(row[0]));
 }
 return rows;
}
function checkRun(run){
 if(run.actId!==ACTOR_ID)throw new Error('The recovery run belongs to a different Actor. Use a BBB Advanced Scraper run.');
 if(['FAILED','ABORTED','TIMED-OUT'].includes(run.status))throw new Error('Apify run '+run.id+' ended '+run.status+'. No business rows were written. Inspect its log; do not treat partial results as a complete observation.');
 if(!['READY','RUNNING','TIMING-OUT','ABORTING','SUCCEEDED'].includes(run.status))throw new Error('Unsupported Actor status: '+run.status);
 return run.status==='SUCCEEDED';
}
function checkDataset(meta){
 if(!Number.isInteger(meta.itemCount)||meta.itemCount<0)throw new Error('Dataset itemCount missing or invalid.');
 if(meta.itemCount===0)throw new Error('BBB returned zero rows. This Actor can also return zero after extraction failure, so inspect its log before calling this an empty search. No business rows changed.');
 if(meta.itemCount>MAX_DATASET)throw new Error('Dataset exceeds the 1000-row safety limit. No silent truncation: use a smaller bounded run.');
 return meta.itemCount;
}
function normalize(item){
 if(typeof item.businessName!=='string'||!item.businessName.trim()||typeof item.reportUrl!=='string')return null;
 // BBB returns relative /us/.../profile/... URLs. Reject external/invalid identities.
 const match=item.reportUrl.match(/^(?:https:\/\/(?:www\.)?bbb\.org)?(\/(?:us|ca)\/[^?#]*\/profile\/[^?#]+)(?:[?#].*)?$/i);
 if(!match)return null;
 const sourceUrl='https://www.bbb.org'+match[1].replace(/\/+$/,'');
 const scalar=v=>v==null?'':String(v).replace(/<\/?em>/gi,'').slice(0,2000);
 const list=v=>Array.isArray(v)?v.map(scalar).join('; '):scalar(v);
 return [sourceUrl,scalar(item.businessName).trim(),scalar(item.address),scalar(item.city),scalar(item.state),scalar(item.postalcode),scalar(item.rating),scalar(item.accreditationStatus),item.bbbMember===true?'true':item.bbbMember===false?'false':'',list(item.categories),list(item.phone)];
}
function ledgerRow(ctx,status,counts={},notes=''){
 const {run,input,executionId}=ctx;
 const event=run.pricingInfo?.pricingPerEvent?.actorChargeEvents?.['apify-default-dataset-item'];
 const count=typeof counts.read==='number'?Math.min(counts.read,run.options?.maxItems??counts.read):undefined;
 const cost=typeof event?.eventPriceUsd==='number'&&typeof count==='number'?Math.round(event.eventPriceUsd*count*1e8)/1e8:'';
 return [run.id,status,input.search,input.location,input.distance??'',run.startedAt,run.finishedAt??'',run.defaultDatasetId,counts.read??'',counts.rejected??'',counts.added??'',counts.updated??'',counts.duplicates??'',cost,run.options?.maxTotalChargeUsd??'',run.buildNumber??'',String(executionId),notes];
}
function planWrites(ctx,items,existing,ledger,datasetCount){
 if(!Array.isArray(items)||items.length!==datasetCount)throw new Error('Dataset retrieval is incomplete. No business rows written.');
 if(!ctx.run.finishedAt||!Number.isFinite(Date.parse(ctx.run.finishedAt)))throw new Error('Completed run timestamp missing.');
 const byKey=new Map(existing.map((r,i)=>[r[0],{row:r,index:i+2}]));
 const known=ledger.findIndex(r=>r[0]===ctx.run.id);
 const ledgerIndex=known>=0?known+2:ledger.length+2;
 if(ledgerIndex>MAX_EXISTING+1)throw new Error('Run log is full. Archive to a new destination.');
 const data=[{range:`'${BUSINESS_TAB}'!A1:P1`,values:[BUSINESS_HEADERS]},{range:`'${RUN_TAB}'!A1:R1`,values:[RUN_HEADERS]}];
 const seen=new Set();const counts={read:items.length,rejected:0,added:0,updated:0,duplicates:0,unchanged:0};
 let nextRow=existing.length+2;
 for(const item of items){
  const base=normalize(item);if(!base){counts.rejected++;continue;}
  const key=base[0];if(seen.has(key)){counts.duplicates++;continue;}seen.add(key);
  const old=byKey.get(key);
  if(old?.row[12]&&!Number.isFinite(Date.parse(old.row[12])))throw new Error('Invalid lastSeenAt in destination; restore the ISO timestamp before replay.');
  if(old?.row[13]===ctx.run.id || (old?.row[12]&&Date.parse(old.row[12])>Date.parse(ctx.run.finishedAt))){counts.unchanged++;continue;}
  const first=old?.row[11]||ctx.run.finishedAt;
  const values=[...base,first,ctx.run.finishedAt,ctx.run.id,ctx.input.search,ctx.input.location];
  const index=old?.index??nextRow++;
  if(index>MAX_EXISTING+1)throw new Error('Business table is full. Archive to a new destination before continuing.');
  data.push({range:`'${BUSINESS_TAB}'!A${index}:P${index}`,values:[values]});
  if(old)counts.updated++;else counts.added++;
 }
 if(seen.size===0)throw new Error('No valid BBB identities found. Possible schema drift; no business rows written.');
 const status=counts.rejected?'PARTIAL_ROWS_REJECTED':'IMPORTED';
 const capped=typeof ctx.run.options?.maxItems==='number'&&items.length>=ctx.run.options.maxItems;
 const notes=(capped?'Charge/result cap reached; bounded sample, not exhaustive. ':'Bounded search observation; not proof of exhaustive coverage. ')+`Replay-safe; ${counts.unchanged} already imported or newer rows preserved.`;
 // Preserve the original successful ledger on same-run replay.
 if(!(known>=0&&['IMPORTED','PARTIAL_ROWS_REJECTED'].includes(ledger[known][1])))data.push({range:`'${RUN_TAB}'!A${ledgerIndex}:R${ledgerIndex}`,values:[ledgerRow(ctx,status,counts,notes)]});
 return {body:{valueInputOption:'RAW',data},summary:{status,runId:ctx.run.id,datasetId:ctx.run.defaultDatasetId,...counts,capped,notes}};
}

return [{json:config($json)}];

